from pathlib import Path
import json,statistics
root=Path(__file__).resolve().parents[1]
data=root.parent/'.ai_prison_game-data'
verification=data/'verification'
latest=json.loads((verification/'latest-assessment.json').read_text(encoding='utf-8'))
suite=json.loads((verification/'suite-results.json').read_text(encoding='utf-8'))['conversations']
models=['openai/gpt-4.1-mini','google/gemini-2.5-flash','qwen/qwen3-235b-a22b-2507','z-ai/glm-5.3-flash']
lines=['# مراجعة اللجنة والإحصاءات — 2026-10-21','',
'أعيد تقييم آخر محادثة مكتملة ذات 30 جولة، وهي `'+latest['session_id']+'`. اكتمل التقييم بتقارير صالحة من GPT-4.1 Mini وGemini 2.5 Flash وQwen3، ثم الحكم النهائي من JEV. حُفظت نسخة من سجل الجلسة قبل إعادة التقييم في مجلد verification الخاص.','',
'## سبب التعطّل والإصلاح','',
'لم يكن العطل انقطاعًا واحدًا عن المزود: GPT-4.1 Mini أعاد تقارير لكن بعض استشهادات كشف الخداع لم تطابق الجولة أو تسلسل الأسئلة. وبعض تقارير Gemini وGLM بلغت حد الإخراج. النظام السابق كان يتوقف عند أول حكم فاشل، فلا يجرب بقية اللجنة. أثناء التشخيص ظهر أيضًا رفض إعداد تعطيل التفكير في طلب GLM؛ عُدّلت إعداداته ثم نجح في الاختبارات اللاحقة.','',
'يستدعي النظام أربعة حكام بالتوازي ويحتاج ثلاثة تقارير صالحة على الأقل. لا تنتقل استجابة مرفوضة أو مبتورة إلى JEV. عند اكتمال الثلاثة يُلغى الطلب الرابع المعلق؛ لا تُحسب هذه الإلغاءات فشلًا للموديل. إذا لم يكتمل النصاب تبقى التقارير الناجحة محفوظة وتظهر أخطاء كل حكم لإعادة المحاولة.','',
'أصبحت الأدلة معرّفات رسائل؛ مثل a12 لرد السجين في الجولة 12 وu13 لسؤال المحقق بعدها. يختار الحكم المرجع، ويستخرج الخادم النص الحرفي من الحوار. لا يُستبدل اقتباس مختلق باقتباس آخر بصمت، ولا تُقبل نقاط إيجابية بلا دليل.','',
'## الاختبارات الحقيقية الإضافية','',
'أُنشئت ثلاثة حوارات اختبار حقيقية، كل منها ثلاث جولات، ثم أُغلقت يدويًا وقُيّمت. استُخدم GPT-4o Mini للسجين وأسئلة تحقيق ثابتة مع JEV للمشاعر. في وضع التحقق فقط انتظرنا الحكام الأربعة، خلاف التشغيل العادي الذي يكتفي بأول ثلاثة. لم تُنشر هذه المحادثات ولم تُضف إلى أرشيف الزوار.','',
'| القضية | الجولات | النتيجة | التقارير الصالحة |','| --- | ---: | --- | ---: |']
for r in suite:
    lines.append(f"| {r['case']} | {r.get('turns','—')} | {r['status']} | {r.get('quorum',{}).get('received',0)} / 4 |")
lines+=['','| الحكم | التقارير المقبولة في الاختبارات الثلاثة | متوسط زمن التقرير |','| --- | ---: | ---: |']
for model in models:
    samples=[r['progress'][model] for r in suite if model in r.get('progress',{})]
    ok=[s for s in samples if s['status']=='complete']
    lines.append(f"| {model} | {len(ok)} / 3 | {statistics.mean(s['seconds'] for s in ok):.1f} ثانية |" if ok else f'| {model} | 0 / 3 | — |')
lines+=['','هذه عينة محدودة لسلامة التكامل، وليست ضمانًا دائمًا. البيانات تشمل نجاح النماذج بعد إصلاح صيغة الأدلة، بينما إحصاءات الواجهة تحتفظ كذلك بالإخفاقات المسجلة أثناء التشخيص.','',
'## سجل الموديول والألوان','',
'كل استدعاء للنموذج يسجل مدة الطلب وزمن أول بايت وعدد توكنات الإخراج المتاحة ونتيجته، في model-health.json وسجل أحداث model-requests.jsonl خارج جذر الموقع. تُحفظ عدادات تراكمية مستقلة عن نافذة العينات؛ لا ينقص عدد الاستخدامات عند حذف عينة قديمة من النافذة. البيانات الأقدم من التتبع التراكمي تستند إلى العينات التي كانت محفوظة آنذاك، وليست استعادة مفترضة لجميع الاستدعاءات المفقودة.','',
'تظهر الواجهة: إجمالي الطلبات المسجلة، النجاحات، الفشل، الإلغاء بعد النصاب، نسبة الفشل، متوسط مدة الطلب، زمن أول بايت، ومتوسط توكنات الإخراج لكل ثانية من إجمالي مدة الطلب الناجح. هذا معدل إجمالي للطلب، وليس قياسًا تدفقيًا للزمن بين توكن وآخر. قد يشمل عداد توكنات المزود توكنات التفكير. أخطاء الاتصال والردود غير الصالحة مصنفة منفصلة.','',
'- أخضر: نسبة الفشل أقل من 10%.','- أصفر: من 10% إلى أقل من 30%.','- برتقالي: 30% فأكثر.','- لا لون للاعتمادية قبل وجود طلب مكتمل مقاس.','',
'تحسب النسبة من الطلبات المكتملة، ولا تدخل الإلغاءات بسبب اكتمال النصاب في المقام أو في عدد الفشل. الأعطال قد تتعلق بحصة المفتاح أو إعداد الطلب أو المزود؛ اللون لا يزعم أن كل فشل عيب في قدرات النموذج. أضيف فرز «الأكثر ثباتًا في قياسات المختبر»، كما يستفيد اختيار لجنة الجلسات الجديدة من السجل مع ترجيح حذر للعينات القليلة.','',
'## التحقق البرمجي','',
'نجحت اختبارات الوحدة والتكامل والمتصفح. تشمل حدود الألوان 9% و10% و29% و30%، بقاء العدد التراكمي بعد تجاوز 100 عينة، عدم عدّ الإلغاء فشلًا، إكمال 3 من 4 عند فشل حكم، وفشل النصاب عند وجود تقريرين فقط مع استكماله لاحقًا دون إعادة شراء التقارير الناجحة.']
(root/'PANEL_RELIABILITY_REVIEW_AR.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Saved PANEL_RELIABILITY_REVIEW_AR.md')
